(ns wadogo.oracle
  "Oracle data (`test/resources/wadogo`, generated by scripts in `utils/`) and comparison predicates."
  (:require [clojure.edn :as edn]
            [clojure.java.io :as io]))

(defn load-oracle
  "Read oracle cases from `test/resources/wadogo/<name>`."
  [name]
  (edn/read-string (slurp (io/resource (str "wadogo/" name)))))

(defn close?
  "Relative closeness (default 1e-12), exact for zero."
  ([a b] (close? a b 1.0e-12))
  ([a b ^double tol]
   (let [a (double a) b (double b)]
     (or (== a b)
         (<= (Math/abs (- a b)) (* tol (max (Math/abs a) (Math/abs b))))))))

(defn close-seqs?
  [xs ys]
  (and (= (count xs) (count ys))
       (every? true? (map close? xs ys))))
